python - <<'PY'
import pathlib
import re
from collections import Counter

base = pathlib.Path("Unimocg_Artifact/evaluation/results/immutability")
cats = {
    "Mutable Field": "mutable",
    "Non Transitively Immutable Field": "non_trans",
    "Dependently Immutable Field": "depen",
    "Transitively Immutable Field": "trans",
}

results = {}

for alg_dir in sorted(base.iterdir()):
    if not alg_dir.is_dir():
        continue
    alg = alg_dir.name
    counts = Counter()
    for txt in alg_dir.glob("*.txt"):
        with txt.open("r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                if " | " not in line:
                    continue
                for marker, key in cats.items():
                    if marker in line:
                        counts[key] += 1
                        break
    results[alg] = counts

def fmt(n: int) -> str:
    s = str(n)
    return s if len(s) <= 3 else s[:-3] + " " + s[-3:]

for alg in ["AdHocCHA", "CHA", "RTA", "XTA"]:
    c = results[alg]
    print(
        f"{alg}: mutable={c['mutable']} "
        f"non_trans={c['non_trans']} depen={c['depen']} trans={c['trans']}"
    )
